private void solve(final FastIO io, final String[] args) {
    io.setAutoFlush(false);
    io.setAutoOutFlush(false);
    int Q = io.nextInt();
    while (Q-- > 0) {
        int X = io.nextInt();
        int n = 1;
        for (int i = 1; i < 100; ++i) if (test(i) % 100 == X % 100) n = i;
        for (int i = 2; i < 9; ++i) {
            int d = pow(10, i), d2 = d * 10;
            for (int j = 0; j < 10; ++j) {
                int n2 = n + d * j;
                if (test(n2) % d2 == X % d2) n = n2;
            }
        }
        io.println(test(n) % 1000000000 == X ? n : -1);
    }
}
